{"query":"fragment pr on PullRequest{number}
		query PullRequestSearch(
			$q: String!,
			$type: SearchType!,
			$limit: Int!,
			$endCursor: String,
		) {
			search(query: $q, type: $type, first: $limit, after: $endCursor) {
				issueCount
				nodes {
					...pr
				}
				pageInfo {
					hasNextPage
					endCursor
				}
			}
		}","variables":{"limit":30,"q":"( 0123456789abcdef0123456789abcdef01234567 ) is:merged repo:example-org/example-repo type:pr","type":"ISSUE_ADVANCED"}}
